import React from 'react';
import { CityGraph, TrafficLevel } from '../types';

interface Props {
  graph: CityGraph;
  highlightPath: string[];
}

const trafficColors: Record<TrafficLevel, string> = {
  Low: '#2ecc71',
  Moderate: '#f1c40f',
  Heavy: '#e74c3c',
  Blocked: '#7f8c8d',
};

const GraphVisualization: React.FC<Props> = ({ graph, highlightPath }) => {
  const isEdgeInPath = (from: string, to: string) => {
    for (let i = 0; i < highlightPath.length - 1; i++) {
      if (
        (highlightPath[i] === from && highlightPath[i + 1] === to) ||
        (highlightPath[i] === to && highlightPath[i + 1] === from)
      ) {
        return true;
      }
    }
    return false;
  };

  return (
    <svg width="100%" height="400" viewBox="0 0 1000 600" style={{ background: '#f8f9fa', borderRadius: '8px' }}>
      {/* Edges */}
      {graph.edges.map((edge, idx) => {
        const fromNode = graph.nodes.find(n => n.id === edge.from)!;
        const toNode = graph.nodes.find(n => n.id === edge.to)!;
        const inPath = isEdgeInPath(edge.from, edge.to);

        return (
          <line
            key={idx}
            x1={fromNode.x}
            y1={fromNode.y}
            x2={toNode.x}
            y2={toNode.y}
            stroke={inPath ? '#3498db' : trafficColors[edge.traffic]}
            strokeWidth={inPath ? 6 : 2}
            strokeDashArray={edge.traffic === 'Blocked' ? '5,5' : '0'}
          />
        );
      })}
      {/* Nodes */}
      {graph.nodes.map(node => (
        <g key={node.id}>
          <circle cx={node.x} cy={node.y} r={20} fill="#2c3e50" />
          <text x={node.x} y={node.y + 5} textAnchor="middle" fill="white" fontSize="14" fontWeight="bold">
            {node.id}
          </text>
          <text x={node.x} y={node.y + 40} textAnchor="middle" fill="#2c3e50" fontSize="12">
            {node.name}
          </text>
        </g>
      ))}
    </svg>
  );
};

export default GraphVisualization;
